window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2a50efd242dfd80b"]={"versions": [{"id": "FIG-2a50efd242dfd80b", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung der internen Kontrollflusslogik der Funktion bzw. des Teilschritts <code>E2E_P02_handle_ok_and_okSomeLost</code> innerhalb der E2E-Profil-2-Prüfroutine (<code>E2E_P02Check</code>). Das Diagramm spezifiziert die Verarbeitungsschritte im AUTOSAR-Basissoftwaremodul <em>E2E Protocol</em> (PRS_E2EProtocol), wenn ein gültiger Counter-Wert empfangen wurde und der Status <code>OK</code>, <code>OKSOMELOST</code> oder <code>SYNC</code> ermittelt werden muss.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustandsstruktur (<code>State</code>)</strong>:</li>\n<li><code>State-&gt;MaxDeltaCounter</code>: Maximal zulässige Differenz zwischen Zählerwerten.</li>\n<li><code>State-&gt;LastValidCounter</code>: Zuletzt als gültig akzeptierter Sequenzzähler.</li>\n<li><code>State-&gt;ReceivedCounter</code>: Aktuell empfangener Sequenzzählerwert.</li>\n<li><code>State-&gt;LostData</code>: Anzahl festgestellter Datenverluste.</li>\n<li><code>State-&gt;NoNewOrRepeatedDataCounter</code>: Zähler für ausgebliebene oder wiederholte Datenrahmen.</li>\n<li><code>State-&gt;SyncCounter</code>: Zähler für die Synchronisationsphase nach Neustart oder Ausfall.</li>\n<li><strong>Konfigurationsstruktur (<code>Config</code>)</strong>:</li>\n<li><code>Config-&gt;MaxDeltaCounterInit</code>: Initialisierungswert für <code>MaxDeltaCounter</code>.</li>\n<li><code>Config-&gt;MaxNoNewOrRepeatedData</code>: Schwellenwert für die maximale Anzahl an fehlenden oder wiederholten Daten.</li>\n<li><code>Config-&gt;SyncCounterInit</code>: Initialisierungswert für den Synchronisationszähler.</li>\n<li><strong>Lokale Variablen / Rückgabewerte</strong>:</li>\n<li><code>DeltaCounter</code>: Berechnete Differenz zwischen <code>ReceivedCounter</code> und <code>LastValidCounter</code>.</li>\n<li><code>returnvalue</code>: Funktionsrückgabewert vom Typ <code>E2E_P02CheckStatusType</code> (<code>E2E_P02STATUS_SYNC</code>, <code>E2E_P02STATUS_OK</code>, <code>E2E_P02STATUS_OKSOMELOST</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Aktualisierung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>State-&gt;MaxDeltaCounter = Config-&gt;MaxDeltaCounterInit</code></li>\n<li><code>State-&gt;LastValidCounter = State-&gt;ReceivedCounter</code></li>\n<li><code>State-&gt;LostData = DeltaCounter - 1</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung Datenlücke / Wiederholung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>State-&gt;NoNewOrRepeatedDataCounter &lt;= Config-&gt;MaxNoNewOrRepeatedData</code>:</li>\n<li><strong>[FALSE]</strong>: <code>State-&gt;SyncCounter = Config-&gt;SyncCounterInit</code>; anschließend wird direkt <code>returnvalue = E2E_P02STATUS_SYNC</code> gesetzt.</li>\n<li><strong>[TRUE]</strong>: Weiterleitung zur Prüfung des Synchronisationsstatus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisationsprüfung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>State-&gt;SyncCounter &gt; 0</code>:</li>\n<li><strong>[TRUE]</strong>: Dekrementierung <code>State-&gt;SyncCounter -= 1</code> und Setzen von <code>returnvalue = E2E_P02STATUS_SYNC</code>.</li>\n<li><strong>[FALSE]</strong>: Prüfung auf Datenverlust via <code>DeltaCounter == 1</code>:</li>\n<li><strong>[TRUE]</strong>: Kein Datenverlust erkannt; Setzen von <code>returnvalue = E2E_P02STATUS_OK</code>.</li>\n<li><strong>[FALSE]</strong>: Datenverlust erkannt; Setzen von <code>returnvalue = E2E_P02STATUS_OKSOMELOST</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zusammenführung aller Pfade über Merge-Knoten.</li>\n<li>Zurücksetzen des Zählers: <code>State-&gt;NoNewOrRepeatedDataCounter = 0</code>.</li>\n<li>Rückgabe des gesetzten <code>returnvalue</code> an den Aufrufer (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Logik realisiert die verbindliche Auswertung der Sequenzüberwachung für AUTOSAR E2E Profile 2 nach erfolgreicher CRC- und Counter-Gültigkeitsprüfung.</li>\n<li>Bei Überschreiten von <code>MaxNoNewOrRepeatedData</code> erzwingt die Routine eine Neusynchronisation (<code>SyncCounterInit</code>), wodurch der Kommunikationsstatus zwingend auf <code>E2E_P02STATUS_SYNC</code> zurückfällt.</li>\n<li>Datenverluste innerhalb des zulässigen Fensters (<code>DeltaCounter &gt; 1</code>) werden über <code>State-&gt;LostData</code> erfasst und führen bei abgeschlossener Synchronisation zu <code>E2E_P02STATUS_OKSOMELOST</code>.</li>\n<li>Vor dem Verlassen der Funktion wird <code>NoNewOrRepeatedDataCounter</code> in jedem Zweig deterministisch auf <code>0</code> gesetzt.</li>\n</ul>"}, {"id": "FIG-2f7a7c2bd16e65d8", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung der internen Kontrollflusslogik der Funktion bzw. des Teilschritts <code>E2E_P02_handle_ok_and_okSomeLost</code> innerhalb der E2E-Profil-2-Prüfroutine (<code>E2E_P02Check</code>). Das Diagramm spezifiziert die Verarbeitungsschritte im AUTOSAR-Basissoftwaremodul <em>E2E Protocol</em> (PRS_E2EProtocol), wenn ein gültiger Counter-Wert empfangen wurde und der Status <code>OK</code>, <code>OKSOMELOST</code> oder <code>SYNC</code> ermittelt werden muss.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustandsstruktur (<code>State</code>)</strong>:</li>\n<li><code>State-&gt;MaxDeltaCounter</code>: Maximal zulässige Differenz zwischen Zählerwerten.</li>\n<li><code>State-&gt;LastValidCounter</code>: Zuletzt als gültig akzeptierter Sequenzzähler.</li>\n<li><code>State-&gt;ReceivedCounter</code>: Aktuell empfangener Sequenzzählerwert.</li>\n<li><code>State-&gt;LostData</code>: Anzahl festgestellter Datenverluste.</li>\n<li><code>State-&gt;NoNewOrRepeatedDataCounter</code>: Zähler für ausgebliebene oder wiederholte Datenrahmen.</li>\n<li><code>State-&gt;SyncCounter</code>: Zähler für die Synchronisationsphase nach Neustart oder Ausfall.</li>\n<li><strong>Konfigurationsstruktur (<code>Config</code>)</strong>:</li>\n<li><code>Config-&gt;MaxDeltaCounterInit</code>: Initialisierungswert für <code>MaxDeltaCounter</code>.</li>\n<li><code>Config-&gt;MaxNoNewOrRepeatedData</code>: Schwellenwert für die maximale Anzahl an fehlenden oder wiederholten Daten.</li>\n<li><code>Config-&gt;SyncCounterInit</code>: Initialisierungswert für den Synchronisationszähler.</li>\n<li><strong>Lokale Variablen / Rückgabewerte</strong>:</li>\n<li><code>DeltaCounter</code>: Berechnete Differenz zwischen <code>ReceivedCounter</code> und <code>LastValidCounter</code>.</li>\n<li><code>returnvalue</code>: Funktionsrückgabewert vom Typ <code>E2E_P02CheckStatusType</code> (<code>E2E_P02STATUS_SYNC</code>, <code>E2E_P02STATUS_OK</code>, <code>E2E_P02STATUS_OKSOMELOST</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Aktualisierung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>State-&gt;MaxDeltaCounter = Config-&gt;MaxDeltaCounterInit</code></li>\n<li><code>State-&gt;LastValidCounter = State-&gt;ReceivedCounter</code></li>\n<li><code>State-&gt;LostData = DeltaCounter - 1</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung Datenlücke / Wiederholung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>State-&gt;NoNewOrRepeatedDataCounter &lt;= Config-&gt;MaxNoNewOrRepeatedData</code>:</li>\n<li><strong>[FALSE]</strong>: <code>State-&gt;SyncCounter = Config-&gt;SyncCounterInit</code>; anschließend wird direkt <code>returnvalue = E2E_P02STATUS_SYNC</code> gesetzt.</li>\n<li><strong>[TRUE]</strong>: Weiterleitung zur Prüfung des Synchronisationsstatus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisationsprüfung</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung <code>State-&gt;SyncCounter &gt; 0</code>:</li>\n<li><strong>[TRUE]</strong>: Dekrementierung <code>State-&gt;SyncCounter -= 1</code> und Setzen von <code>returnvalue = E2E_P02STATUS_SYNC</code>.</li>\n<li><strong>[FALSE]</strong>: Prüfung auf Datenverlust via <code>DeltaCounter == 1</code>:</li>\n<li><strong>[TRUE]</strong>: Kein Datenverlust erkannt; Setzen von <code>returnvalue = E2E_P02STATUS_OK</code>.</li>\n<li><strong>[FALSE]</strong>: Datenverlust erkannt; Setzen von <code>returnvalue = E2E_P02STATUS_OKSOMELOST</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zusammenführung aller Pfade über Merge-Knoten.</li>\n<li>Zurücksetzen des Zählers: <code>State-&gt;NoNewOrRepeatedDataCounter = 0</code>.</li>\n<li>Rückgabe des gesetzten <code>returnvalue</code> an den Aufrufer (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Logik realisiert die verbindliche Auswertung der Sequenzüberwachung für AUTOSAR E2E Profile 2 nach erfolgreicher CRC- und Counter-Gültigkeitsprüfung.</li>\n<li>Bei Überschreiten von <code>MaxNoNewOrRepeatedData</code> erzwingt die Routine eine Neusynchronisation (<code>SyncCounterInit</code>), wodurch der Kommunikationsstatus zwingend auf <code>E2E_P02STATUS_SYNC</code> zurückfällt.</li>\n<li>Datenverluste innerhalb des zulässigen Fensters (<code>DeltaCounter &gt; 1</code>) werden über <code>State-&gt;LostData</code> erfasst und führen bei abgeschlossener Synchronisation zu <code>E2E_P02STATUS_OKSOMELOST</code>.</li>\n<li>Vor dem Verlassen der Funktion wird <code>NoNewOrRepeatedDataCounter</code> in jedem Zweig deterministisch auf <code>0</code> gesetzt.</li>\n</ul>"}], "trans": [{"from": "FIG-2a50efd242dfd80b", "to": "FIG-2f7a7c2bd16e65d8", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
